const $=id=>document.getElementById(id);const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
import {addOffer} from '../cart.js';
async function init(){const slug=/^\/marketplace\/service\/([a-z0-9-]+)$/.exec(location.pathname)?.[1];if(!slug){$('detail-status').textContent='Service not found.';return}try{const r=await fetch('/api/marketplace/services/'+encodeURIComponent(slug));if(r.status===404){$('detail-status').textContent='This service is unavailable.';return}if(!r.ok)throw Error();const j=await r.json();if(!j.success)throw Error();const s=j.data;document.title=(s.seo_title||s.title)+' | Leakendia';for(const k of ['title','summary','description'])$(k).textContent=s[k]||'';for(const m of s.media||[]){const img=el('img');img.src='/api/marketplace/media/'+encodeURIComponent(m.id);img.alt=m.alt_text||'';img.loading='lazy';$('gallery').append(img);$('gallery').hidden=false}const labels={scope:'Scope',deliverable:'Deliverables',exclusion:'Exclusions',requirement:'Requirements',faq:'Frequently asked questions'};for(const [kind,label] of Object.entries(labels)){const rows=(s.content||[]).filter(c=>c.kind===kind);if(!rows.length)continue;const panel=el('section',undefined,'mp-panel');panel.append(el('h2',label));for(const c of rows){const block=el(kind==='faq'?'details':'div',undefined,'mp-offer');block.append(el(kind==='faq'?'summary':'h3',c.title),el('p',c.body));panel.append(block)}$('content').append(panel)}for(const o of s.offers||[]){const block=el('div',undefined,'mp-offer');let price='Request a quote';if(o.price_minor!=null)price=new Intl.NumberFormat('en-US',{style:'currency',currency:o.currency}).format(o.price_minor/100)+(o.model==='weekly'?' / week':'');block.append(el('h3',o.name),el('p',price),el('p',o.delivery_days?`${o.delivery_days} day delivery`:''));for(const [label,go] of [['Add to Cart',false],['Request This Service',true]]){const a=el('button',label,'btn btn-primary');a.type='button';a.onclick=async()=>{a.disabled=true;try{await addOffer(s,o,go);if(!go)a.textContent='Added to cart';}catch(e){a.textContent='Try again';alert(e.message);}finally{a.disabled=false;}};block.append(a);}$('offers').append(block)}if(!$('offers').children.length)$('offers').textContent='Contact us for pricing.';for(const item of s.related||[]){const p=el('p');const a=el('a',item.title);a.href='/marketplace/service/'+encodeURIComponent(item.slug);p.append(a);$('related-links').append(p);$('related').hidden=false}$('detail').hidden=false;$('detail-status').hidden=true}catch{$('detail-status').textContent='Unable to load this service. Please try again later.'}}init();
